    },
    {
      "headline": "DPP and KMT clash over Taipei's rodent infestation problem",
      "summary": "DPP Taipei City Councilor Hsu Shu-hua accused the KMT-led Taipei City government of being slow to address a significant rodent problem in the city; KMT countered that the DPP was 'aggressively politicizing' the issue and spreading misinformation."
    },
    {
      "headline": "TSMC taps offshore wind power to address energy crunch from AI chip manufacturing demand",
      "summary": "TSMC signed a 30-year agreement to purchase more than 1 gigawatt of power capacity from three offshore wind sites off central Taiwan operated by Canada's Northland Power, as the chipmaker's AI-driven manufacturing expansion strains Taiwan's energy grid."
    },
